import{_ as t,a}from"./chunks/android-02-aide-dans-l-app-fermer.Dswwg5UN.js";import{_ as r,o as i,c as n,a5 as o}from"./chunks/framework.CslsFoWx.js";const d="/VendoraSystem-docs/captures/2026-11-08-borne-aide-acces-guide/01-ecran-technique-aide-en-ligne.webp",s="/VendoraSystem-docs/captures/2026-11-08-borne-aide-acces-guide/02-aide-dans-l-app-fermer.webp",_=JSON.parse(`{"title":"Borne : aide en ligne ouverte dans l'application (08/11/2026)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-08-borne-aide-acces-guide.md","filePath":"generated/preuves/2026-11-08-borne-aide-acces-guide.md","lastUpdated":null}`),l={name:"preuves/2026-11-08-borne-aide-acces-guide.md"};function u(c,e,p,m,g,b){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="borne-aide-en-ligne-ouverte-dans-l-application-08-11-2026" tabindex="-1">Borne : aide en ligne ouverte dans l&#39;application (08/11/2026) <a class="header-anchor" href="#borne-aide-en-ligne-ouverte-dans-l-application-08-11-2026" aria-label="Permalink to &quot;Borne : aide en ligne ouverte dans l&#39;application (08/11/2026)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-08-borne-aide-acces-guide</code> · 0 image(s) · 0 trace(s)</p><div><p>Carte Trello « P3 · Borne iOS : ouvrir l&#39;aide en ligne sous Accès guidé ». iPad Air 11&quot; simulé (simulateur dédié), borne appairée au commerce FICTIF « Le Petit Bistrot (démo) » sur le serveur du worktree ; écran technique ouvert par 5 touchers en haut à gauche puis le PIN de la manager de démo.</p><p><strong>Cause</strong> : l&#39;entrée « Aide en ligne » de l&#39;écran technique était un lien vers Safari. Sous Accès guidé, iPadOS limite l&#39;appareil à une seule app (documentation Apple, « Utiliser l&#39;Accès guidé » : l&#39;appareil reste dans l&#39;app) : l&#39;ouverture de Safari est bloquée, le lien ne faisait rien. Même situation sur Android avec l&#39;épinglage / Lock Task Mode (autre app interdite). Correctif : aide ouverte dans l&#39;app — WKWebView (iOS, pas de bouton « Ouvrir dans Safari » comme SFSafariViewController) et WebView (Android) en plein écran, bouton « Fermer l&#39;aide », navigation limitée au centre d&#39;aide, message hors ligne, rien de conservé entre deux consultations.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="'+d+'" alt="Écran technique"></td><td>Écran technique : « Aide en ligne » (1).</td></tr><tr><td><img src="'+s+'" alt="Aide dans l&#39;app"></td><td><strong>Après</strong> : l&#39;aide s&#39;ouvre dans l&#39;app, rubrique Borne (2) ; « Fermer l&#39;aide » (1) revient à l&#39;écran technique. Avant : rien ne s&#39;ouvrait sous Accès guidé.</td></tr></tbody></table><p>Capture faite sans Accès guidé actif (il ne s&#39;active pas sur un simulateur piloté) : le comportement est le même, l&#39;aide ne quitte plus l&#39;app.</p><h2 id="captures-android-tablette-08-11-2026-au-soir" tabindex="-1">Captures Android (tablette, 08/11/2026 au soir) <a class="header-anchor" href="#captures-android-tablette-08-11-2026-au-soir" aria-label="Permalink to &quot;Captures Android (tablette, 08/11/2026 au soir)&quot;">​</a></h2><p>Captures Android faites le 08/11/2026 au soir sur les émulateurs du projet (dérogation accordée pour ce lot) : tablette <code>emulator-5554</code> (AVD « Kds_Tablet », 1600 × 1000) et téléphone <code>emulator-5556</code> (AVD « Medium_Phone_API_36.1 », 1080 × 2400), app de debug <code>pos.android</code> construite depuis <code>main</code> (0d1aecf5), commerce de démo FICTIF « Le Petit Bistrot (démo) » (<code>bistrot.demo+and1108@vendora.test</code>, <code>seed-demo.py --no-activity</code>) sur le serveur de dev <code>localhost:8080</code>. Gestes par <code>help/tools/mobile/drv.py</code> (adb), annotations par <code>annotate.py</code>. Borne appairée (preset « Borne entrée »), écran technique ouvert par 5 touchers en haut à gauche puis le PIN de la manager de démo. Scénario : <code>help/tools/mobile/scenarios/borne-mode-technique-borne-android.json</code>.</p><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle montre</th></tr></thead><tbody><tr><td><img src="'+t+'" alt=""></td><td>Écran technique Android : <strong>Aide en ligne</strong> (1), Désappairer cet appareil (2), retour à la borne (3).</td></tr><tr><td><img src="'+a+'" alt=""></td><td><code>OnlineHelpInAppDialog</code> : l&#39;aide s&#39;ouvre <strong>dans l&#39;app</strong> (WebView), rubrique Borne (2), <strong>Fermer l&#39;aide</strong> (1) revient à l&#39;écran technique.</td></tr></tbody></table><p>Capture prise borne <strong>non épinglée</strong> (épinglage refusé juste avant) : la vue web est la même, l&#39;aide ne quitte pas l&#39;app.</p><p><strong>Défauts vus</strong> :</p><ul><li>La barre d&#39;en-tête de l&#39;aide (« Fermer l&#39;aide », « Aide en ligne ») est dessinée <strong>sous la barre d&#39;état</strong> : l&#39;heure et les icônes du système chevauchent le haut du bouton « Fermer l&#39;aide » (encarts système non appliqués à la vue plein écran).</li><li>Écran technique Android : sous le badge DEV, un libellé gris « Synchroniser » isolé (doublon du bouton) ; le bouton de retour s&#39;intitule « Commandez ici » (texte de l&#39;accueil client) au lieu de « Retour à la borne » comme sur iOS ; « Aide en ligne » a un style plus petit que les autres boutons. Les actions iOS « Clôturer la journée » / terminal de paiement n&#39;apparaissent pas (borne sans terminal configuré : à vérifier).</li></ul></div>',3)])])}const A=r(l,[["render",u]]);export{_ as __pageData,A as default};
